function bitwiseComplement(n) {
  if (n === 0) {
    return 1;
  }
  let mask = 0;
  let rest = n;
  while (rest > 0) {
    mask = (mask << 1) | 1;
    rest >>= 1;
  }
  return n ^ mask;
}

